import matplotlib.pyplot as plt

FRONT_HEIGHTS = [200,202,204,208,212,216,220,225,230,235,240,250,260,275,290,310,330,360,400,420,450,500,550,600]  # microns
G_SLOPES = [0.30021118779555744,0.31904732388815027,0.34935513238801824,0.4282489090965559,0.506499688009871,0.5779691317361701,0.6416464060262671,0.7104538498626253,0.7682753606636629,0.8164324668959271,0.8562514556389962,0.9156995776059207,0.9551222710143351,0.9899256077753286,1.0072163487344483,1.0159984854731567,1.0165366651608259,1.0113840625594475,1.001719064764048,0.9968544855388909,0.9899662164162187,0.9797688066133343,0.9713646882880638,0.9642371762336691]  # degrees/mm

# Bounds are (lower, upper); fit uses r=(h-BACK_HEIGHT)/(h+BACK_HEIGHT).
G_BOUNDS = [(0.2998463263329813, 0.3005760492581336), (0.3186492996511686, 0.3194453481251319), (0.3488470706492361, 0.3498631941268004), (0.42752945698988726, 0.4289683612032245), (0.5058912013194301, 0.5071081747003119), (0.5776348091989061, 0.5783034542734342), (0.6408582156546518, 0.6424345963978824), (0.7083700939242988, 0.7125376058009517), (0.7647146757673274, 0.7718360455599983), (0.8114410963049026, 0.8214238374869516), (0.8500075828031007, 0.8624953284748916), (0.907692706908742, 0.9237064483030993), (0.946367145987944, 0.9638773960407262), (0.9816021606121001, 0.998249054938557), (1.0004907964153953, 1.0139419010535013), (1.0121874501613057, 1.0198095207850078), (1.0153419675429105, 1.0177313627787412), (1.007612705689003, 1.015155419429892), (0.9932486066579409, 1.010189522870155), (0.9864113523744262, 1.0072976187033555), (0.9770033988277608, 1.0029290340046766), (0.9632848539331392, 0.9962527592935294), (0.9519846667439424, 0.9907447098321851), (0.9422437619909232, 0.986230590476415)]
BASELINE, AMPLITUDE, SCALE, SHAPE, DECAY = 0.2969624676306401, 0.7706658218149393, 0.07079050925478324, 1.302184163681769, 0.2739076106601732
BACK_HEIGHT = 200  # microns, using the doubled-height convention

plt.figure(figsize=(8, 6))
plt.errorbar(FRONT_HEIGHTS, G_SLOPES, yerr=[[g - lo for g, (lo, hi) in zip(G_SLOPES, G_BOUNDS)], [hi - g for g, (lo, hi) in zip(G_SLOPES, G_BOUNDS)]], fmt="o", color="tab:blue", capsize=3, ms=6, label="Simulation (80 nodes)")
heights = [FRONT_HEIGHTS[0] + (FRONT_HEIGHTS[-1] - FRONT_HEIGHTS[0]) * i / 399 for i in range(400)]
slopes = [BASELINE + AMPLITUDE * (1 - 2.718281828459045 ** (-((((h - BACK_HEIGHT) / (h + BACK_HEIGHT)) / SCALE) ** SHAPE))) * 2.718281828459045 ** (-DECAY * (h - BACK_HEIGHT) / (h + BACK_HEIGHT)) for h in heights]
plt.plot(heights, slopes, color="black", lw=2, label="Smooth response fit")
plt.xlabel(r"Front plate height $h_{\mathrm{front}}$ ($\mu$m)")
plt.ylabel(r"Chirality slope $d\alpha/dx$ ($^\circ$/mm)")
plt.grid(True, alpha=0.25)
plt.legend()
plt.savefig("cant_simple.png", dpi=300, bbox_inches="tight")
